// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/// @title CrossServiceAuthenticator
/// @notice Handles authentication between gRPC microservices via on-chain verification
/// @dev Used by the gRPC gateway to validate service-to-service JWT-like tokens
contract CrossServiceAuthenticator {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct ServiceCredential {
        address signer;
        uint256 nonce;
        uint256 registeredAt;
        bytes32 serviceRole;
    }

    struct AuthRequest {
        bytes32 serviceId;
        bytes32 targetServiceId;
        uint256 timestamp;
        uint256 nonce;
        bytes payload;
    }

    mapping(bytes32 => ServiceCredential) public services;
    mapping(bytes32 => mapping(uint256 => bool)) public usedNonces;
    mapping(bytes32 => bytes32) private serviceKeyDerivationSeed;

    address public admin;
    uint256 public constant AUTH_WINDOW = 300; // 5 minutes
    bytes32 public immutable DOMAIN_SEPARATOR;

    event ServiceRegistered(bytes32 indexed serviceId, address signer);
    event AuthCompleted(bytes32 indexed from, bytes32 indexed to, uint256 timestamp);
    event KeyRotated(bytes32 indexed serviceId, address newSigner);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor(bytes32 domainSalt) {
        admin = msg.sender;
        DOMAIN_SEPARATOR = keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes("CrossServiceAuth")),
            keccak256(bytes("1")),
            block.chainid,
            address(this)
        ));
    }

    function registerService(
        bytes32 serviceId,
        address signer,
        bytes32 role,
        bytes32 keyDerivationSeed
    ) external onlyAdmin {
        require(services[serviceId].signer == address(0), "Already registered");
        require(signer != address(0), "Invalid signer");

        services[serviceId] = ServiceCredential({
            signer: signer,
            nonce: 0,
            registeredAt: block.timestamp,
            serviceRole: role
        });

        serviceKeyDerivationSeed[serviceId] = keyDerivationSeed;
        emit ServiceRegistered(serviceId, signer);
    }

    /// @notice Derives the authentication key material for cross-service calls
    /// @dev The derived key is used by the gRPC interceptor for HMAC signing
    function deriveAuthKey(
        bytes32 sourceServiceId,
        bytes32 targetServiceId
    ) public view returns (bytes32) {
        require(services[sourceServiceId].signer != address(0), "Source not registered");
        require(services[targetServiceId].signer != address(0), "Target not registered");

        // Derive a shared key between two services using their seeds
        bytes32 sourceSeed = serviceKeyDerivationSeed[sourceServiceId];
        bytes32 targetSeed = serviceKeyDerivationSeed[targetServiceId];

        // Symmetric derivation: key(A->B) == key(B->A) for bidirectional auth
        bytes32 combinedSeed = _combineSeeds(sourceSeed, targetSeed);

        return keccak256(abi.encodePacked(
            DOMAIN_SEPARATOR,
            combinedSeed,
            services[sourceServiceId].serviceRole,
            services[targetServiceId].serviceRole
        ));
    }

    function _combineSeeds(bytes32 a, bytes32 b) internal pure returns (bytes32) {
        // XOR-based combination ensures commutativity: combine(a,b) == combine(b,a)
        return a ^ b;
    }

    function authenticateRequest(
        AuthRequest calldata request,
        bytes calldata signature
    ) external returns (bool) {
        require(block.timestamp <= request.timestamp + AUTH_WINDOW, "Request expired");
        require(block.timestamp >= request.timestamp - 60, "Request from future");
        require(!usedNonces[request.serviceId][request.nonce], "Nonce reused");

        ServiceCredential storage source = services[request.serviceId];
        require(source.signer != address(0), "Service not registered");

        bytes32 requestHash = _hashAuthRequest(request);
        bytes32 ethSignedHash = requestHash.toEthSignedMessageHash();

        address recovered = ethSignedHash.recover(signature);
        require(recovered == source.signer, "Invalid signature");

        usedNonces[request.serviceId][request.nonce] = true;
        source.nonce++;

        emit AuthCompleted(request.serviceId, request.targetServiceId, request.timestamp);
        return true;
    }

    function _hashAuthRequest(AuthRequest calldata request) internal view returns (bytes32) {
        return keccak256(abi.encodePacked(
            DOMAIN_SEPARATOR,
            request.serviceId,
            request.targetServiceId,
            request.timestamp,
            request.nonce,
            keccak256(request.payload)
        ));
    }

    function rotateServiceKey(
        bytes32 serviceId,
        address newSigner,
        bytes calldata adminSignature
    ) external {
        require(services[serviceId].signer != address(0), "Not registered");

        bytes32 rotationHash = keccak256(abi.encodePacked(
            "ROTATE",
            serviceId,
            newSigner,
            services[serviceId].nonce
        ));

        address recovered = rotationHash.toEthSignedMessageHash().recover(adminSignature);
        require(recovered == admin, "Invalid admin signature");

        services[serviceId].signer = newSigner;
        services[serviceId].nonce++;

        // Key derivation seed is NOT rotated - maintains backward compatibility
        // with existing cross-service authentication channels

        emit KeyRotated(serviceId, newSigner);
    }

    /// @notice Batch verify multiple service authentications (used by gRPC load balancer)
    function batchAuthenticate(
        AuthRequest[] calldata requests,
        bytes[] calldata signatures
    ) external returns (bool[] memory results) {
        require(requests.length == signatures.length, "Length mismatch");
        results = new bool[](requests.length);

        for (uint256 i = 0; i < requests.length; i++) {
            try this.authenticateRequest(requests[i], signatures[i]) returns (bool result) {
                results[i] = result;
            } catch {
                results[i] = false;
            }
        }
    }

    function getServiceInfo(bytes32 serviceId) external view returns (
        address signer,
        uint256 nonce,
        uint256 registeredAt,
        bytes32 role
    ) {
        ServiceCredential storage cred = services[serviceId];
        return (cred.signer, cred.nonce, cred.registeredAt, cred.serviceRole);
    }
}
